/// 🆔️ Every collection of this family removed by row id, never by position.
pub const ID_REMOVALS: &[IdRemoval] = &[
        IdRemoval { path: "cases", kind: "remove-case", selectors: &[], id: "id" },
        IdRemoval { path: "walls[].loadCases[].concentrated", kind: "remove-concentrated", selectors: &[SelectorKey::Id("wallId"), SelectorKey::Id("loadCaseId")], id: "id" },
        IdRemoval { path: "walls[].loadCases", kind: "remove-load-case", selectors: &[SelectorKey::Id("wallId")], id: "id" },
        IdRemoval { path: "walls[].openings", kind: "remove-opening", selectors: &[SelectorKey::Id("wallId")], id: "id" },
        IdRemoval { path: "walls", kind: "remove-wall", selectors: &[], id: "id" },
        IdRemoval { path: "walls[].piers", kind: "remove-pier", selectors: &[SelectorKey::Id("wallId")], id: "id" },
        IdRemoval { path: "walls[].lintels", kind: "remove-lintel", selectors: &[SelectorKey::Id("wallId")], id: "id" },
        IdRemoval { path: "walls[].ties", kind: "remove-tie", selectors: &[SelectorKey::Id("wallId")], id: "id" },
        IdRemoval { path: "walls[].prestress", kind: "remove-prestress", selectors: &[SelectorKey::Id("wallId")], id: "id" },
        IdRemoval { path: "walls[].confined", kind: "remove-confined", selectors: &[SelectorKey::Id("wallId")], id: "id" },
        IdRemoval { path: "walls[].flanges", kind: "remove-flange", selectors: &[SelectorKey::Id("wallId")], id: "id" },
        IdRemoval { path: "walls[].bars", kind: "remove-bar", selectors: &[SelectorKey::Id("wallId")], id: "id" },
        IdRemoval { path: "placements", kind: "remove-placement", selectors: &[], id: "id" },
        IdRemoval { path: "chases", kind: "remove-chase", selectors: &[], id: "id" },
        IdRemoval { path: "movementJoints", kind: "remove-movement-joint", selectors: &[], id: "id" },
];

/// 🎯️ Resolves an editor edit into concrete kind mutations: row-id removals by [`ID_REMOVALS`], every other path through [`EDIT_RULES`].
pub fn resolve_edit(document: &En1996Snapshot, edit: &NormEdit) -> Result<Vec<En1996Mutation>, String> {
    EDIT_RULES.resolve_with_id_removals(ID_REMOVALS, document, edit)
}
